	"testing"
)

func TestSolve(t *testing.T) {
	cases := []struct {
		in, want []int
	}{
		{[]int{1, 2, 3}, []int{2, 4, 6}},
		{[]int{}, []int{}},
		{[]int{-5}, []int{-10}},
	}
	for _, c := range cases {
		got := Solve(c.in)
		if len(c.want) == 0 && len(got) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("Solve(%v)=%v want %v", c.in, got, c.want)
		}
	}
}

